1	package promptcompression
2	
3	import (
4		"math"
5		"runtime"
6		"sync"
7	)
8	
9	// TextRankScorer implements the TextRank algorithm for sentence importance scoring.
10	//
11	// Reference: Mihalcea, R. and Tarau, P. (2004). "TextRank: Bringing Order into
12	// Text." Proceedings of EMNLP 2004. ACL Anthology W04-3252.
13	//
14	// The algorithm models the document as a graph where sentences are nodes and
15	// edges are weighted by lexical similarity (cosine of TF vectors). It then
16	// runs a PageRank-style iterative computation to propagate importance scores
17	// through the graph. Sentences that are similar to many other important
18	// sentences receive higher scores — capturing the centrality intuition that
19	// the most "representative" sentences are the most important.
20	type TextRankScorer struct {
21		dampingFactor float64
22		maxIterations int
23		convergence   float64
24	}
25	
26	// NewTextRankScorer creates a TextRank scorer with standard parameters.
27	// The damping factor of 0.85 follows the original PageRank paper
28	// (Brin & Page, 1998) and is the value used in Mihalcea & Tarau (2004).
29	func NewTextRankScorer() *TextRankScorer {
30		return &TextRankScorer{
31			dampingFactor: 0.85,
32			maxIterations: 100,
33			convergence:   1e-5,
34		}
35	}
36	
37	// float64SlicePool reduces GC pressure from the PageRank power iteration.
38	// Each iteration needs a temporary []float64 of length n; pooling avoids
39	// allocating it on every pass.
40	var float64SlicePool = sync.Pool{
41		New: func() interface{} {
42			s := make([]float64, 0, 128)
43			return &s
44		},
45	}
46	
47	// adjacencyPool holds flat []float64 matrices (n*n) for TextRank.
48	// At maxSentences=500, this is 500*500*8 = 2MB — large enough that
49	// recycling avoids measurable GC pressure on the hot path.
50	var adjacencyPool = sync.Pool{
51		New: func() interface{} {
52			s := make([]float64, 0, 256*256)
53			return &s
54		},
55	}
56	
57	func getFloat64Slice(n int) []float64 {
58		sp := float64SlicePool.Get().(*[]float64)
59		s := *sp
60		if cap(s) >= n {
61			s = s[:n]
62		} else {
63			s = make([]float64, n)
64		}
65		for i := range s {
66			s[i] = 0
67		}
68		return s
69	}
70	
71	func putFloat64Slice(s []float64) {
72		s = s[:0]
73		float64SlicePool.Put(&s)
74	}
75	
76	func getAdjacencyMatrix(n int) []float64 {
77		size := n * n
78		sp := adjacencyPool.Get().(*[]float64)
79		s := *sp
80		if cap(s) >= size {
81			s = s[:size]
82		} else {
83			s = make([]float64, size)
84		}
85		for i := range s {
86			s[i] = 0
87		}
88		return s
89	}
90	
91	func putAdjacencyMatrix(s []float64) {
92		s = s[:0]
93		adjacencyPool.Put(&s)
94	}
95	
96	// ScoreSentences computes TextRank importance scores for each sentence.
97	// Input: a slice of token lists (one per sentence). Output: normalized scores in [0, 1].
98	// This is the backward-compatible entry point that builds TF vectors internally.
99	func (tr *TextRankScorer) ScoreSentences(sentenceTokens [][]string) []float64 {
100		n := len(sentenceTokens)
101		if n == 0 {
102			return nil
103		}
104		if n == 1 {
105			return []float64{1.0}
106		}
107		tfVecs := make([]map[string]float64, n)
108		for i, tokens := range sentenceTokens {
109			tfVecs[i] = termFrequency(tokens)
110		}
111		return tr.scoreSentencesFromTF(n, tfVecs)
112	}
113	
114	// ScoreSentencesWithTF computes TextRank scores using pre-computed TF vectors,
115	// avoiding duplicate map allocations when the caller already has TF data.
116	func (tr *TextRankScorer) ScoreSentencesWithTF(tfVecs []map[string]float64) []float64 {
117		n := len(tfVecs)
118		if n == 0 {
119			return nil
120		}
121		if n == 1 {
122			return []float64{1.0}
123		}
124		return tr.scoreSentencesFromTF(n, tfVecs)
125	}
126	
127	// scoreSentencesFromTF is the shared implementation.
128	//
129	// GC note: the adjacency matrix is stored as a flat []float64 (row-major) instead
130	// of [][]float64 to avoid n slice-header allocations and improve cache locality.
131	// The matrix is obtained from a sync.Pool to avoid re-allocating n*n*8 bytes per call.
132	func (tr *TextRankScorer) scoreSentencesFromTF(n int, tfVecs []map[string]float64) []float64 {
133		weights := getAdjacencyMatrix(n)
134		defer putAdjacencyMatrix(weights)
135	
136		// Pre-compute L2 norms so the pairwise loop avoids redundant iteration.
137		norms := make([]float64, n)
138		for i, tf := range tfVecs {
139			var sq float64
140			for _, v := range tf {
141				sq += v * v
142			}
143			norms[i] = math.Sqrt(sq)
144		}
145	
146		// Parallelize pairwise cosine computation for large n. The threshold
147		// avoids goroutine overhead when n is small. Each goroutine writes to
148		// non-overlapping (i,j)/(j,i) cells so no synchronization is needed
149		// beyond the WaitGroup.
150		const parallelThreshold = 64
151		if n >= parallelThreshold {
152			numWorkers := runtime.GOMAXPROCS(0)
153			if numWorkers > n {
154				numWorkers = n
155			}
156			var wg sync.WaitGroup
157			wg.Add(numWorkers)
158			chunkSize := (n + numWorkers - 1) / numWorkers
159			for w := 0; w < numWorkers; w++ {
160				lo := w * chunkSize
161				hi := lo + chunkSize
162				if hi > n {
163					hi = n
164				}
165				go func(lo, hi int) {
166					defer wg.Done()
167					for i := lo; i < hi; i++ {
168						for j := i + 1; j < n; j++ {
169							sim := cosineSimilarityWithNorms(tfVecs[i], tfVecs[j], norms[i], norms[j])
170							weights[i*n+j] = sim
171							weights[j*n+i] = sim
172						}
173					}
174				}(lo, hi)
175			}
176			wg.Wait()
177		} else {
178			for i := 0; i < n; i++ {
179				for j := i + 1; j < n; j++ {
180					sim := cosineSimilarityWithNorms(tfVecs[i], tfVecs[j], norms[i], norms[j])
181					weights[i*n+j] = sim
182					weights[j*n+i] = sim
183				}
184			}
185		}
186	
187		outSum := make([]float64, n)
188		for i := 0; i < n; i++ {
189			row := weights[i*n : (i+1)*n]
190			for _, w := range row {
191				outSum[i] += w
192			}
193		}
194	
195		// Build the transition matrix T in-place: T[i][j] = weights[j][i] / outSum[j].
196		// Since weights is symmetric, weights[j][i] == weights[i][j], so
197		// T[i][j] = weights[i][j] / outSum[j]. The power iteration inner loop then
198		// becomes a row-major dot product (cache-friendly) instead of column-access.
199		for i := 0; i < n; i++ {
200			row := weights[i*n : (i+1)*n]
201			for j := 0; j < n; j++ {
202				if i == j || outSum[j] == 0 {
203					row[j] = 0
204				} else {
205					row[j] /= outSum[j]
206				}
207			}
208		}
209	
210		scores := make([]float64, n)
211		for i := range scores {
212			scores[i] = 1.0 / float64(n)
213		}
214	
215		d := tr.dampingFactor
216		base := (1.0 - d) / float64(n)
217	
218		newScores := getFloat64Slice(n)
219		defer putFloat64Slice(newScores)
220	
221		for iter := 0; iter < tr.maxIterations; iter++ {
222			maxDelta := 0.0
223	
224			for i := 0; i < n; i++ {
225				var sum float64
226				row := weights[i*n : (i+1)*n]
227				for j := 0; j < n; j++ {
228					sum += row[j] * scores[j]
229				}
230				newScores[i] = base + d*sum
231				delta := math.Abs(newScores[i] - scores[i])
232				if delta > maxDelta {
233					maxDelta = delta
234				}
235			}
236	
237			scores, newScores = newScores, scores
238			if maxDelta < tr.convergence {
239				break
240			}
241			for i := range newScores {
242				newScores[i] = 0
243			}
244		}
245	
246		// Normalize to [0, 1]
247		maxScore := 0.0
248		for _, s := range scores {
249			if s > maxScore {
250				maxScore = s
251			}
252		}
253		if maxScore > 0 {
254			for i := range scores {
255				scores[i] /= maxScore
256			}
257		}
258	
259		return scores
260	}
261	
262	// cosineSimilarityWithNorms computes cosine similarity using pre-computed L2 norms.
263	// Only the dot product requires map iteration; the denominator is norms[i]*norms[j].
264	// Iterates the smaller map for the dot product to minimize hash lookups.
265	func cosineSimilarityWithNorms(tfA, tfB map[string]float64, normA, normB float64) float64 {
266		denom := normA * normB
267		if denom == 0 {
268			return 0
269		}
270		small, large := tfA, tfB
271		if len(tfA) > len(tfB) {
272			small, large = tfB, tfA
273		}
274		var dot float64
275		for term, fs := range small {
276			if fl, ok := large[term]; ok {
277				dot += fs * fl
278			}
279		}
280		return dot / denom
281	}
282	
283	// cosineSimilarityFromTF computes cosine similarity from pre-computed TF maps.
284	// Iterates the smaller map for the dot product to minimize hash lookups.
285	func cosineSimilarityFromTF(tfA, tfB map[string]float64) float64 {
286		if len(tfA) == 0 || len(tfB) == 0 {
287			return 0
288		}
289	
290		small, large := tfA, tfB
291		if len(tfA) > len(tfB) {
292			small, large = tfB, tfA
293		}
294	
295		var dot, normSmall, normLarge float64
296		for term, fs := range small {
297			normSmall += fs * fs
298			if fl, ok := large[term]; ok {
299				dot += fs * fl
300			}
301		}
302		for _, fl := range large {
303			normLarge += fl * fl
304		}
305	
306		denom := math.Sqrt(normSmall) * math.Sqrt(normLarge)
307		if denom == 0 {
308			return 0
309		}
310		return dot / denom
311	}
312	
313	// cosineSimilarity computes cosine similarity between two token bags.
314	// Kept for test compatibility; the hot path uses cosineSimilarityFromTF.
315	func cosineSimilarity(a, b []string) float64 {
316		if len(a) == 0 || len(b) == 0 {
317			return 0
318		}
319		return cosineSimilarityFromTF(termFrequency(a), termFrequency(b))
320	}
321	
