7	// TFIDFScorer computes TF-IDF-based information density scores for sentences.
8	//
9	// This implements a token-level information measure inspired by Selective Context
10	// (Li et al. 2023, "Compressing Context to Enhance Inference Efficiency of Large
11	// Language Models", EMNLP 2023, arXiv:2310.06201). Selective Context uses
12	// self-information from a causal LM; we approximate this with TF-IDF which
13	// captures the same intuition: rare, informative tokens have high inverse
14	// document frequency and therefore high self-information.
15	//
16	// IDF(t) = log(N / df(t)) is proportional to the self-information of a token
17	// under a unigram corpus model: I(t) = -log P(t) ≈ log(N/df(t)).
18	type TFIDFScorer struct {
19		docFreq  map[string]int
20		numDocs  int
21		idfCache map[string]float64
22	}
23	
24	// NewTFIDFScorer builds document-frequency statistics from a set of sentence token lists.
25	//
26	// GC note: pre-sizes maps based on estimated vocabulary size to avoid
27	// repeated map growth for large documents. The "seen" set uses a reusable
28	// map that is cleared between sentences instead of allocating a new one.
29	func NewTFIDFScorer(sentenceTokens [][]string) *TFIDFScorer {
30		totalTokens := 0
31		for _, tokens := range sentenceTokens {
32			totalTokens += len(tokens)
33		}
34		// Rough estimate: unique vocabulary ≈ sqrt(total tokens) for natural language (Heaps' law)
35		vocabEstimate := totalTokens
36		if vocabEstimate > 256 {
37			vocabEstimate = int(math.Sqrt(float64(totalTokens)) * 3)
38		}
39	
40		s := &TFIDFScorer{
41			docFreq:  make(map[string]int, vocabEstimate),
42			numDocs:  len(sentenceTokens),
43			idfCache: make(map[string]float64, vocabEstimate),
44		}
45	
46		// Reuse a single "seen" map across sentences to avoid per-sentence allocation.
47		seen := make(map[string]bool, 64)
48		for _, tokens := range sentenceTokens {
49			for k := range seen {
50				delete(seen, k)
51			}
52			for _, t := range tokens {
53				if !seen[t] {
54					s.docFreq[t]++
55					seen[t] = true
56				}
57			}
58		}
59	
60		return s
61	}
